import{_ as s,a0 as p,w as l,s as u,I as i,x as r,a1 as e,A as a,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"用 CrowPi 樹莓派套件瞭解關於計算機的一切 | LCTT x X-CMD","titleTemplate":false,"description":"用 CrowPi 樹莓派套件瞭解關於計算機的一切 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 CrowPi 樹莓派套件瞭解關於計算機的一切 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 CrowPi 樹莓派套件瞭解關於計算機的一切 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20210906 Learn everything about computers with this Raspberry Pi kit","title":"用 CrowPi 樹莓派套件瞭解關於計算機的一切","tag":"202303","desc":""},"relativePath":"202303/20210906 Learn everything about computers with this Raspberry Pi kit.md","filePath":"[post].md"}'),d={name:"202303/20210906 Learn everything about computers with this Raspberry Pi kit.md"};function m(P,t,f,w,C,g){const o=p("Link");return l(),u("div",null,[t[37]||(t[37]=i("h1",{id:"用-crowpi-樹莓派套件瞭解關於計算機的一切",tabindex:"-1"},[r("用 CrowPi 樹莓派套件瞭解關於計算機的一切 "),i("a",{class:"header-anchor",href:"#用-crowpi-樹莓派套件瞭解關於計算機的一切","aria-label":"Permalink to “用 CrowPi 樹莓派套件瞭解關於計算機的一切”"},"​")],-1)),t[38]||(t[38]=i("blockquote",null,[i("p",null,"CrowPi 是一個超棒的樹莓派項目系統，安裝在一個筆記本電腦般的外殼裏。")],-1)),t[39]||(t[39]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202303/24/170210th71d0o707worogv.jpg",alt:""})],-1)),i("p",null,[t[1]||(t[1]=r("我喜歡歷史，也喜歡計算機，因此相比於計算機如何變成個人配件，我更喜歡聽它在成為日常家用電器前的故事。",-1)),e(o,{href:"https://opensource.com/article/21/8/my-first-programming-language"},{default:a(()=>[...t[0]||(t[0]=[r("我經常聽到的一個故事",-1)])]),_:1}),t[2]||(t[2]=r(" 是很久以前（反正在計算機時代算久遠了）的計算機是多麼的簡單。事實上，它們簡單到對於一個好奇的用户來説，弄清楚如何編程並不是十分困難。再看看現代計算機，它具有面向對象的編程語言、複雜的 GUI 框架、網絡 API、容器等，但愈發令人擔憂的是，計算工具正變得越來越難懂，對於那些沒有接受過專門培訓的人來説基本上無法使用。",-1))]),t[40]||(t[40]=n('<p>從樹莓派在 2012 年發佈之日起，它就一直被定位為一個教育平台。一些第三方供應商通過附加組件和培訓套件支持樹莓派，以幫助所有年齡段的學習者探索編程、物理計算和開源。然而，直到最近，很大程度上還是要由用户來弄清楚市場上的所有部件如何組合在一起，直到我最近買了 CrowPi。</p><p><img src="https://opensource.com/sites/default/files/crowpi-not-laptop.jpeg" alt="CrowPi 不是一個筆記本電腦" title="CrowPi more than a laptop"></p><h3 id="crowpi2-介紹" tabindex="-1">CrowPi2 介紹 <a class="header-anchor" href="#crowpi2-介紹" aria-label="Permalink to “CrowPi2 介紹”">​</a></h3><p>烏鴉是非常聰明的鳥。它們能識別並記住面孔，模仿聽到的聲音，解決複雜的謎題，甚至使用工具來完成任務。CrowPi 使用烏鴉作為其徽標和名字是恰當的，因為這個設備充滿了探索、實驗、教育的機會，最重要的是，充滿了樂趣。</p><p>其設計很巧妙：它看起來像筆記本電腦，但遠不止於此。當你從機殼中取出藍牙鍵盤時，它會顯示一個隱藏的電子設備工坊，配有 LCD 屏幕、16 個按鈕、刻度盤、RFID 傳感器、接近傳感器、線路板、揚聲器、GPIO 連接、LED 陣列等等。<em>而且這一切都是可編程的。</em></p><p>顧名思義，該裝置本身完全由樹莓派提供支持，它牢固地固定在機殼底部。</p><p><img src="https://opensource.com/sites/default/files/crowpi-pi.jpeg" alt="CrowPi 的樹莓派板" title="crowpi pi board"></p><p>默認情況下，你應該用電源適配器為設備充電，包裝附帶一個壁式插頭，你可以將其插入機殼，而不是直接為樹莓派供電。你還可以使用插入外部微型 USB 端口的電池電源。機殼內甚至還有一個抽屜，方便你存放電池。這樣做的時候，有一根 USB 線從電池抽屜中彈出，並插入機殼電源端口，因此你不會產生這是一台“普通”筆記本電腦的錯覺。然而，這樣一台設備能夠有如此美觀的設計已經很理想了！</p><h3 id="首次啓動系統" tabindex="-1">首次啓動系統 <a class="header-anchor" href="#首次啓動系統" aria-label="Permalink to “首次啓動系統”">​</a></h3>',9)),i("p",null,[t[4]||(t[4]=r("CrowPi2 提供一張安裝了 Raspbian 系統，貼有 “System” 標籤的 microSD 卡，不過它同時還提供了裝載 ",-1)),e(o,{href:"https://opensource.com/article/19/1/retropie"},{default:a(()=>[...t[3]||(t[3]=[r("RetroPie",-1)])]),_:1}),t[5]||(t[5]=r(" 的第二張 microSD 卡。作為一個負責任的成年人（咳咳），我自然是先啓動了 RetroPie。",-1))]),t[41]||(t[41]=n('<p>RetroPie 總是很有趣，CrowPi2 附帶兩個超任風格的遊戲控制器，確保你能獲得最佳的復古遊戲體驗。</p><p>令人讚歎不已的是，啓動實際的 Raspbian 系統的過程同樣有趣，甚至可以説更有趣。它的登錄管理器是一個自定義項目中心，有一些快速鏈接，如編程示例項目、Python 和 Arduino IDE、Scratch、Python 示例遊戲、Minecraft 等。你也可以選擇退出項目中心，只使用桌面。</p><p><img src="https://opensource.com/sites/default/files/crowpi-hub.png" alt="CrowPi 中心" title="CrowPi hub"></p><p>對於習慣使用樹莓派或 Linux 的人來説，CrowPi 桌面很熟悉，不過它也足夠簡單，所以很容易上手。左上角有應用程序菜單，桌面上有快捷圖標，右上角有網絡選擇和音量控制的系統托盤等等。</p><p><img src="https://opensource.com/sites/default/files/crowpi-desktop.png" alt="CrowPi 桌面" title="CrowPi desktop"></p><p>CrowPi 上有很多東西可供選擇，所以你可能很難決定從哪裏開始。對我來説，主要分為四大類：編程、物理電子學、Linux 和遊戲。</p><p>盒子裏有一本使用説明，所以你會知道你需要怎樣進行連接（例如，鍵盤是電池供電的，所以它有時確實需要充電，它和鼠標總是需要一個 USB 適配器）。雖然説明書很快就能讀完，但這一例子也充分體現了 CrowPi 團隊是如何認真對待説明書的。</p><p><img src="https://opensource.com/sites/default/files/crowpi-docs.jpeg" alt="CrowPi 文檔" title="CrowPi docs"></p><h3 id="編程" tabindex="-1">編程 <a class="header-anchor" href="#編程" aria-label="Permalink to “編程”">​</a></h3><p>如果你想學習如何編碼，在 CrowPi 上有很多成功的途徑。你可以從中選擇你覺得最滿意的路徑。</p><h4 id="_1、scratch" tabindex="-1">1、Scratch <a class="header-anchor" href="#_1、scratch" aria-label="Permalink to “1、Scratch”">​</a></h4>',11)),i("p",null,[e(o,{href:"https://opensource.com/article/20/9/scratch"},{default:a(()=>[...t[6]||(t[6]=[r("Scratch",-1)])]),_:1}),t[8]||(t[8]=r(" 是一個簡單的可視化編碼應用程序，可讓你像拼 ",-1)),e(o,{href:"https://opensource.com/article/20/6/open-source-virtual-lego"},{default:a(()=>[...t[7]||(t[7]=[r("樂高積木",-1)])]),_:1}),t[9]||(t[9]=r(" 一樣將代碼塊組合在一起，製作出遊戲和互動故事。這是開啓編程之旅最簡單的方法，我曾見過年僅 8 歲的孩子會花數小時來研究自己設計的遊戲的最佳算法。當然，它不僅適合孩子們！成年人也可以從中獲得很多樂趣。不知道從哪裏開始？包裝盒中有一本 99 頁的小冊子（打印在紙張上），其中包含 Scratch 課程和項目供你嘗試。",-1))]),t[42]||(t[42]=i("h4",{id:"_2、java-和-minecraft",tabindex:"-1"},[r("2、Java 和 Minecraft "),i("a",{class:"header-anchor",href:"#_2、java-和-minecraft","aria-label":"Permalink to “2、Java 和 Minecraft”"},"​")],-1)),i("p",null,[t[13]||(t[13]=r("Minecraft 不是開源的（雖然有 ",-1)),e(o,{href:"https://opensource.com/alternatives/minecraft"},{default:a(()=>[...t[10]||(t[10]=[r("幾個開源項目",-1)])]),_:1}),t[14]||(t[14]=r(" 復刻了它），但它有足夠的可用資源，因此也經常被用來教授編程。Minecraft 是用 Java 編寫的，CrowPi 同時裝載有 ",-1)),e(o,{href:"https://www.minecraft.net/en-us/edition/pi"},{default:a(()=>[...t[11]||(t[11]=[r("Minecraft Pi Edition",-1)])]),_:1}),t[15]||(t[15]=r(" 和 ",-1)),e(o,{href:"https://opensource.com/article/20/7/ide-java#bluej"},{default:a(()=>[...t[12]||(t[12]=[r("BlueJ Java IDE",-1)])]),_:1}),t[16]||(t[16]=r(" ，如此可使學習 Java 變得比以往更容易、更有趣。",-1))]),t[43]||(t[43]=i("h4",{id:"_3、python-和-pygame",tabindex:"-1"},[r("3、Python 和 PyGame "),i("a",{class:"header-anchor",href:"#_3、python-和-pygame","aria-label":"Permalink to “3、Python 和 PyGame”"},"​")],-1)),i("p",null,[t[19]||(t[19]=r("CrowPi 上有幾個非常有趣的遊戲，它們是用 Python 和 ",-1)),e(o,{href:"https://opensource.com/downloads/python-gaming-ebook"},{default:a(()=>[...t[17]||(t[17]=[r("PyGame 遊戲引擎",-1)])]),_:1}),t[20]||(t[20]=r(" 編寫的。你可以玩這些遊戲，然後查看其源代碼以瞭解遊戲的運行方式。CrowPi 中包含 Geany、Thonny 和 ",-1)),e(o,{href:"https://opensource.com/article/18/8/getting-started-mu-python-editor-beginners"},{default:a(()=>[...t[18]||(t[18]=[r("Mu",-1)])]),_:1}),t[21]||(t[21]=r(" 編輯器，因此你可以使用 Python 立即開始編程。與 Scratch 一樣，包裝盒中有一本包含有課程的小冊子，因此你可以學習 Python 基礎知識。",-1))]),t[44]||(t[44]=n('<h3 id="電子器件" tabindex="-1">電子器件 <a class="header-anchor" href="#電子器件" aria-label="Permalink to “電子器件”">​</a></h3><p>隱藏在鍵盤下的物理電子工坊本質上是一系列 Pi Hat（附着在上的硬件）。為了讓你可以認識所有的組件，CrowPi 繪製了一張中英雙語的摺頁圖進行詳細的説明。除此之外還有很多示例項目可以幫助你入門。 以下是一張小清單：</p><ul><li><strong>你好</strong>：當你與 CrowPi 説話時，LCD 屏幕上打印輸出“你好”。</li><li><strong>入侵警報</strong>：使用接近傳感器發出警報。</li><li><strong>遠程控制器</strong>：讓你能夠使用遠程控制（是的，這個也包含在盒子裏）來觸發 CrowPi 上的事件。</li><li><strong>RGB 俄羅斯方塊</strong>：讓你可以在 LED 顯示屏上玩俄羅斯方塊遊戲。</li><li><strong>語音識別</strong>：演示自然語言處理。</li><li><strong>超聲波音樂</strong>：利用距離傳感器和揚聲器創建簡易版的 <ruby>特雷門琴<rt>Theramin</rt></ruby>（LCTT 譯註：世上唯一不需要身體接觸的電子樂器）。</li></ul><p>這些項目僅僅是入門級別而已，因為你還可以在現有的基礎上搭建更多東西。當然，還有更多內容值得探索。包裝盒裏還有網絡跳線、電阻、LED 和各種組件，這樣你閒暇時也可以瞭解樹莓派的 GPIO （通用輸入輸出端口）功能的所有信息。</p><p>不過我也發現了一個問題：示例項目的位置有點難找。找到演示項目很容易（它們就在 CrowPi 中心上），但源代碼的位置並不是很容易被找到。我後來發現大多數示例項目都在 <code>/usr/share/code</code> 中，你可以通過文件管理器或終端進行訪問。</p><p><img src="https://opensource.com/sites/default/files/crowpi-peripherals.jpeg" alt="CrowPi 外圍設備" title="CrowPi peripherals"></p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h3><p>樹莓派上運行的是 Linux 系統。如果你一直想更深入瞭解 Linux，那麼 CrowPi 同樣會是一個很好的平台。你可以探索 Linux 桌面、終端以及幾乎所有 Linux 或開源應用程序。如果你多年來一直在閲讀有關開源的文章，並準備深入研究開源操作系統，那麼 CrowPi 會是你想要的平台（當然還有很多其他平台也可以）。</p><h3 id="遊戲" tabindex="-1">遊戲 <a class="header-anchor" href="#遊戲" aria-label="Permalink to “遊戲”">​</a></h3><p>包裝盒中包含的 <strong>RetroPie</strong> SD 卡意味着你可以重新啓動切換為復古遊戲機，並任意玩各種老式街機遊戲。它跟 Steam Deck 並不完全相同，但也是一個有趣且令人振奮的小遊戲平台。因為它配備的不是一個而是兩個遊戲控制器，所以它非常適合多人合作的沙發遊戲。最重要的是，你不僅可以在 CrowPi 上玩遊戲，還可以製作自己的遊戲。</p><h3 id="配備螺絲刀" tabindex="-1">配備螺絲刀 <a class="header-anchor" href="#配備螺絲刀" aria-label="Permalink to “配備螺絲刀”">​</a></h3><p>自我坐下開始使用 CrowPi2 以來已經大約兩週，但我還沒有通關所有項目。有很多個晚上，我不得不強迫自己停下襬弄它，因為即使我厭倦了一個項目，我也會不可避免地發現還有其他東西可以探索。總而言之，我在盒子裏找到了一個特別的組件，這個組件讓我馬上知道 CrowPi 和我就是天造地設：它是一把不起眼的小螺絲刀。盒子上沒有撕開就不保修的標籤。CrowPi 希望你去修補、拆解、探索和學習。它不是筆記本電腦，甚至也不僅僅是個樹莓派；而是一個便攜的、低功耗的、多樣化的、開源的學習者工具包。</p><hr>',13)),i("p",null,[t[23]||(t[23]=r("via: ",-1)),e(o,{href:"https://opensource.com/article/21/9/raspberry-pi-crowpi2"},{default:a(()=>[...t[22]||(t[22]=[r("https://opensource.com/article/21/9/raspberry-pi-crowpi2",-1)])]),_:1})]),i("p",null,[t[28]||(t[28]=r("作者：",-1)),e(o,{href:"https://opensource.com/users/seth"},{default:a(()=>[...t[24]||(t[24]=[r("Seth Kenlon",-1)])]),_:1}),t[29]||(t[29]=r(" 選題：",-1)),e(o,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[25]||(t[25]=[r("lujun9972",-1)])]),_:1}),t[30]||(t[30]=r(" 譯者：",-1)),e(o,{href:"https://github.com/XiaotingHuang22"},{default:a(()=>[...t[26]||(t[26]=[r("XiaotingHuang22",-1)])]),_:1}),t[31]||(t[31]=r(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:a(()=>[...t[27]||(t[27]=[r("wxy",-1)])]),_:1})]),i("p",null,[t[34]||(t[34]=r("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[32]||(t[32]=[r("LCTT",-1)])]),_:1}),t[35]||(t[35]=r(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:a(()=>[...t[33]||(t[33]=[r("Linux中國",-1)])]),_:1}),t[36]||(t[36]=r(" 榮譽推出",-1))])])}const x=s(d,[["render",m]]);export{T as __pageData,x as default};
